/**
 * CopilotKit Adapter for Ollama
 *
 * <RequestExample>
 * ```jsx CopilotRuntime Example
 * const copilotKit = new CopilotRuntime();
 * return copilotKit.response(req, new OllamaAdapter());
 * ```
 * </RequestExample>
 *
 * You can easily set the model to use by passing it to the constructor.
 * ```jsx
 * const copilotKit = new CopilotRuntime();
 * return copilotKit.response(
 *   req,
 *   new OllamaAdapter({ model: "llama3-70b-8192" }),
 * );
 * ```
 */
import type { TextMessage } from "../../../graphql/types/converted";
import type {
  CopilotServiceAdapter,
  CopilotRuntimeChatCompletionRequest,
  CopilotRuntimeChatCompletionResponse,
} from "../../service-adapter";
import { randomId, randomUUID } from "@copilotkit/shared";
import { createOpenAI } from "@ai-sdk/openai";
import type { LanguageModel } from "ai";

const DEFAULT_MODEL = "llama3:latest";

const DEFAULT_BASE_URL = "http://127.0.0.1:11434";

interface OllamaAdapterOptions {
  model?: string;
  /**
   * Base URL of the Ollama server. Defaults to `http://127.0.0.1:11434`.
   */
  baseUrl?: string;
}

export class ExperimentalOllamaAdapter implements CopilotServiceAdapter {
  public model: string;
  public provider = "ollama";
  private baseUrl: string;
  public get name() {
    return "OllamaAdapter";
  }

  constructor(options?: OllamaAdapterOptions) {
    this.baseUrl = options?.baseUrl ?? DEFAULT_BASE_URL;
    if (options?.model) {
      this.model = options.model;
    } else {
      this.model = DEFAULT_MODEL;
    }
  }

  async process(
    request: CopilotRuntimeChatCompletionRequest,
  ): Promise<CopilotRuntimeChatCompletionResponse> {
    const { messages, actions, eventSource } = request;
    // const messages = this.transformMessages(forwardedProps.messages);

    // eslint-disable-next-line @typescript-eslint/no-var-requires
    const { Ollama } = require("@langchain/community/llms/ollama");
    const ollama = new Ollama({
      model: this.model,
    });
    const contents = (
      messages.filter((m) => m.isTextMessage()) as TextMessage[]
    ).map((m) => m.content);
    const _stream = await ollama.stream(contents); // [TODO] role info is dropped...

    eventSource.stream(async (eventStream$) => {
      const currentMessageId = randomId();
      eventStream$.sendTextMessageStart({ messageId: currentMessageId });
      for await (const chunkText of _stream) {
        eventStream$.sendTextMessageContent({
          messageId: currentMessageId,
          content: chunkText,
        });
      }
      eventStream$.sendTextMessageEnd({ messageId: currentMessageId });
      // we may need to add this later.. [nc]
      // let calls = (await result.response).functionCalls();

      eventStream$.complete();
    });
    return {
      threadId: request.threadId || randomUUID(),
    };
  }

  /**
   * Ollama exposes an OpenAI-compatible API at `/v1`, so the model is built
   * from the OpenAI provider pointed at the Ollama server. Without it the
   * runtime rebuilds a bare "ollama/<model>" string and fails with
   * `Unknown provider "ollama"`. Ollama ignores the key; a non-empty value is
   * required only because the OpenAI client insists on one.
   */
  getLanguageModel(): LanguageModel {
    const provider = createOpenAI({
      baseURL: `${this.baseUrl.replace(/\/$/, "")}/v1`,
      apiKey: "ollama",
    });
    return provider(this.model);
  }
}
